#include <WiFi.h>
#include <WebServer.h>
#include <Update.h>
#include <Adafruit_NeoPixel.h>

// =====================================================
// WIFI SETTINGS
// =====================================================

const char* ssid     = "TP-Link S4";
const char* password = "tzp33cs8pu";

// =====================================================
// WS2811 LED STRIP
// 12V / 150 physical LEDs
// 3 LEDs per addressable group = 50 pixels
// =====================================================

#define LED_PIN        27
#define LED_COUNT      50
#define LED_BRIGHTNESS 150

Adafruit_NeoPixel strip(
  LED_COUNT,
  LED_PIN,
  NEO_GRB + NEO_KHZ800
);

// =====================================================
// WEB SERVER
// =====================================================

WebServer server(80);

// =====================================================
// OTA UPDATE WEB PAGE
// =====================================================

const char* updatePage = R"rawliteral(
