// =====================================================
// SET ENTIRE LED STRIP TO ONE COLOR
// =====================================================

void setAll(byte r, byte g, byte b) {

  for (int i = 0; i < LED_COUNT; i++) {

    strip.setPixelColor(
      i,
      strip.Color(r, g, b)
    );

  }

  strip.show();
}


// =====================================================
// OTA SERVER
// =====================================================

void setupOTA() {

  // ---------------------------------------------------
  // MAIN FIRMWARE UPDATE PAGE
  // ---------------------------------------------------

  server.on("/", HTTP_GET, []() {

    server.send(
      200,
      "text/html",
      updatePage
    );

  });


  // ---------------------------------------------------
  // FIRMWARE UPLOAD
  // ---------------------------------------------------

  server.on(

    "/update",

    HTTP_POST,


    // -------------------------------------------------
    // UPDATE COMPLETE
    // -------------------------------------------------

    []() {

      if (Update.hasError()) {

        server.send(
          500,
          "text/plain",
          "UPDATE FAILED"
        );

      }

      else {

        server.send(
          200,
          "text/plain",
          "UPDATE SUCCESSFUL - REBOOTING"
        );

        delay(1000);

        ESP.restart();

      }

    },


    // -------------------------------------------------
    // RECEIVE FIRMWARE DATA
    // -------------------------------------------------

    []() {

      HTTPUpload& upload = server.upload();


      // -----------------------------------------------
      // UPLOAD START
      // -----------------------------------------------

      if (upload.status == UPLOAD_FILE_START) {

        Serial.println();

        Serial.println(
          "============================"
        );

        Serial.println(
          "OTA UPDATE STARTING"
        );

        Serial.println(
          "============================"
        );

        Serial.print(
          "Filename: "
        );

        Serial.println(
          upload.filename
        );


        if (!Update.begin(UPDATE_SIZE_UNKNOWN)) {

          Update.printError(Serial);

        }

      }


      // -----------------------------------------------
      // RECEIVE FIRMWARE
      // -----------------------------------------------

      else if (upload.status == UPLOAD_FILE_WRITE) {

        if (
          Update.write(
            upload.buf,
            upload.currentSize
          )
          !=
          upload.currentSize
        ) {

          Update.printError(Serial);

        }

      }


      // -----------------------------------------------
      // UPLOAD FINISHED
      // -----------------------------------------------

      else if (upload.status == UPLOAD_FILE_END) {

        if (Update.end(true)) {

          Serial.println();

          Serial.println(
            "============================"
          );

          Serial.println(
            "OTA UPDATE SUCCESSFUL"
          );

          Serial.println(
            "============================"
          );

          Serial.print(
            "Firmware size: "
          );

          Serial.print(
            upload.totalSize
          );

          Serial.println(
            " bytes"
          );

        }

        else {

          Serial.println();

          Serial.println(
            "============================"
          );

          Serial.println(
            "OTA UPDATE FAILED"
          );

          Serial.println(
            "============================"
          );

          Update.printError(Serial);

        }

      }

    }

  );


  // ---------------------------------------------------
  // START WEB SERVER
  // ---------------------------------------------------

  server.begin();

  Serial.println(
    "OTA web server started."
  );

}


// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(115200);

  delay(500);


  // ---------------------------------------------------
  // INITIALIZE WS2811
  // ---------------------------------------------------

  strip.begin();

  strip.setBrightness(
    LED_BRIGHTNESS
  );

  strip.clear();

  strip.show();


  // ---------------------------------------------------
  // CONNECT TO WIFI
  // ---------------------------------------------------

  WiFi.mode(WIFI_STA);

  WiFi.begin(
    ssid,
    password
  );


  Serial.println();

  Serial.println(
    "============================"
  );

  Serial.println(
    "ESP32 STARTING"
  );

  Serial.println(
    "============================"
  );

  Serial.print(
    "Connecting to "
  );

  Serial.println(
    ssid
  );


  while (
    WiFi.status() != WL_CONNECTED
  ) {

    delay(500);

    Serial.print(".");

  }


  // ---------------------------------------------------
  // WIFI CONNECTED
  // ---------------------------------------------------

  Serial.println();
  Serial.println();

  Serial.println(
    "============================"
  );

  Serial.println(
    "WIFI CONNECTED!"
  );

  Serial.println(
    "============================"
  );

  Serial.print(
    "IP Address: "
  );

  Serial.println(
    WiFi.localIP()
  );

  Serial.print(
    "Signal: "
  );

  Serial.print(
    WiFi.RSSI()
  );

  Serial.println(
    " dBm"
  );


  // ---------------------------------------------------
  // START OTA
  // ---------------------------------------------------

  setupOTA();


  // ---------------------------------------------------
  // TURN ENTIRE STRIP HOT PINK
  // ---------------------------------------------------

  setAll(
    255,   // Red
    0,     // Green
    100    // Blue
  );

}


// =====================================================
// MAIN LOOP
// =====================================================

void loop() {

  // Keep the OTA web server responsive
  server.handleClient();

}
